from typing import Annotated

from fastapi import Depends, FastAPI, HTTPException, status
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm

app = FastAPI()
oauth2 = OAuth2PasswordBearer(tokenUrl="token")
USERS = {"alice": {"hash": hasher.hash("secret123"), "role": "admin"}}
HASH_LEURRE = hasher.hash("leurre")               # anti-énumération (temps constant)

@app.post("/token")
def login(form: Annotated[OAuth2PasswordRequestForm, Depends()]):
    user = USERS.get(form.username)
    ok = hasher.verify(form.password, user["hash"] if user else HASH_LEURRE) and user is not None
    if not ok:
        raise HTTPException(401, "Identifiants invalides", headers={"WWW-Authenticate": "Bearer"})
    access, _ = creer_token(form.username, "access", timedelta(minutes=15))
    refresh, _ = creer_token(form.username, "refresh", timedelta(days=7))
    return {"access_token": access, "refresh_token": refresh, "token_type": "bearer"}

def utilisateur_courant(token: Annotated[str, Depends(oauth2)]) -> dict:
    try:
        return USERS[lire_token(token, "access")["sub"]]
    except (jwt.InvalidTokenError, KeyError):
        raise HTTPException(status.HTTP_401_UNAUTHORIZED, "Jeton invalide",
                            headers={"WWW-Authenticate": "Bearer"}) from None

def admin(user: Annotated[dict, Depends(utilisateur_courant)]) -> dict:
    if user["role"] != "admin":
        raise HTTPException(status.HTTP_403_FORBIDDEN, "Réservé aux administrateurs")
    return user

@app.post("/predict")
def predict(user: Annotated[dict, Depends(utilisateur_courant)]):
    return {"prediction": 0.87}

