def b64(s: str) -> dict:
    return json.loads(base64.urlsafe_b64decode(s + "=" * (-len(s) % 4)))

print(b64("eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9"))   # {'alg': 'HS256', 'typ': 'JWT'}
print(b64("eyJzdWIiOiJhbGljZSIsImV4cCI6MTczNTY4OTYwMH0"))   # {'sub': 'alice', 'exp': 1735689600}
